stage_a_raw:
{
  "decisions": [
    {
      "decision": "machine_assignment_scope",
      "evidence": "\"Operations from different jobs may share the same machine\" and \"the order of operations on shared machines must be determined\"",
      "options": [
        "Create ordering binaries for every unordered pair of distinct operations (all pairs contend for a machine)",
        "Create ordering binaries only for pairs of operations from different jobs (same-job operations never share a machine)",
        "Create ordering binaries only for the two operations of each job (each job's operations share one machine)"
      ],
      "plausibility": [
        0.5,
        0.3,
        0.2
      ],
      "majority_option": "Create ordering binaries for every unordered pair of distinct operations (all pairs contend for a machine)"
    },
    {
      "decision": "start_time_domain",
      "evidence": "\"The start time of each operation must be non-negative\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "makespan_domain",
      "evidence": "\"The makespan must be at least as large as the completion time of every operation\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "precedence_gap_direction",
      "evidence": "\"the start time of an operation in a job must be at least 1 unit after the completion of the previous operation in the same job\"",
      "options": [
        "s[j,1] >= s[j,0] + 1 (strictly after completion)",
        "s[j,1] >= s[j,0] + 1 with equality allowed only (s[j,1] = s[j,0] + 1)",
        "s[j,1] >= s[j,0] (start at or after previous start)"
      ],
      "plausibility": [
        0.9,
        0.05,
        0.05
      ],
      "majority_option": "s[j,1] >= s[j,0] + 1 (strictly after completion)"
    },
    {
      "decision": "makespan_constraint_direction",
      "evidence": "\"The makespan must be at least as large as the completion time of every operation across all jobs\"",
      "options": [
        "Cmax >= s[j,o] + p for all operations",
        "Cmax = s[j,o] + p for the last operation only",
        "Cmax <= s[j,o] + p for all operations"
      ],
      "plausibility": [
        0.95,
        0.03,
        0.02
      ],
      "majority_option": "Cmax >= s[j,o] + p for all operations"
    },
    {
      "decision": "objective_definition",
      "evidence": "\"Minimize the total completion time (makespan)\"",
      "options": [
        "minimize Cmax (maximum completion time)",
        "minimize sum of all operation completion times"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "minimize Cmax (maximum completion time)"
    }
  ]
}
